import [printf] from "std/c.bpl";

# Simple enum - no associated data
enum Color {
    Red,
    Green,
    Blue,
    Yellow,
}

enum Direction {
    North,
    South,
    East,
    West,
}

frame printColor(c: Color) {
    match (c) {
        Color.Red => printf("Red\n"),
        Color.Green => printf("Green\n"),
        Color.Blue => printf("Blue\n"),
        Color.Yellow => printf("Yellow\n"),
    }
}

frame move(dir: Direction) {
    match (dir) {
        Direction.North => printf("Moving north ↑\n"),
        Direction.South => printf("Moving south ↓\n"),
        Direction.East => printf("Moving east →\n"),
        Direction.West => printf("Moving west ←\n"),
    }
}

frame main() ret int {
    local myColor: Color = Color.Blue;
    printf("My color: ");
    printColor(myColor);

    local heading: Direction = Direction.North;
    move(heading);
    move(Direction.East);

    return 0;
}

import [printf] from "std/c.bpl";

# Enum where variants hold different data
enum Shape {
    Circle(int),           # radius
    Rectangle(int, int),   # width, height
    Triangle(int, int, int), # three sides
}

frame describeShape(s: Shape) {
    match (s) {
        Shape.Circle(r) => {
            printf("Circle with radius %d\n", r);
        },
        Shape.Rectangle(w, h) => {
            printf("Rectangle %d x %d\n", w, h);
        },
        Shape.Triangle(a, b, c) => {
            printf("Triangle with sides %d, %d, %d\n", a, b, c);
        },
    }
}

frame area(s: Shape) ret int {
    local result: int = 0;
    match (s) {
        Shape.Circle(r) => {
            result = 3 * r * r;  # Approximation: π ≈ 3
        },
        Shape.Rectangle(w, h) => {
            result = w * h;
        },
        Shape.Triangle(a, b, c) => {
            # Simplified: just return perimeter/2 as approximation
            result = (a + b + c) / 2;
        },
    }
    return result;
}

frame main() ret int {
    local circle: Shape = Shape.Circle(5);
    local rect: Shape = Shape.Rectangle(10, 20);
    local tri: Shape = Shape.Triangle(3, 4, 5);

    describeShape(circle);
    printf("Area: ~%d\n\n", area(circle));

    describeShape(rect);
    printf("Area: %d\n\n", area(rect));

    describeShape(tri);
    printf("Semi-perimeter: %d\n", area(tri));

    return 0;
}

import [printf] from "std/c.bpl";

# Option represents a value that may or may not exist
enum Option<T> {
    Some(T),  # Has a value
    None,     # No value
}

# Safe division - returns None for division by zero
frame safeDivide(a: int, b: int) ret Option<int> {
    if (b == 0) {
        return Option.None;
    }
    return Option.Some(a / b);
}

# Find element in array - returns None if not found
frame find(arr: *int, len: int, target: int) ret Option<int> {
    loop (local i: int = 0; i < len; i = i + 1) {
        if (*(arr + i) == target) {
            return Option.Some(i);  # Return index
        }
    }
    return Option.None;
}

frame main() ret int {
    # Safe division
    printf("10 / 2 = ");
    match (safeDivide(10, 2)) {
        Option.Some(result) => printf("%d\n", result),
        Option.None => printf("undefined\n"),
    }

    printf("10 / 0 = ");
    match (safeDivide(10, 0)) {
        Option.Some(result) => printf("%d\n", result),
        Option.None => printf("undefined\n"),
    }

    # Find in array
    local data: int[5] = [10, 20, 30, 40, 50];

    printf("\nFind 30: ");
    match (find(&data[0], 5, 30)) {
        Option.Some(idx) => printf("found at index %d\n", idx),
        Option.None => printf("not found\n"),
    }

    printf("Find 99: ");
    match (find(&data[0], 5, 99)) {
        Option.Some(idx) => printf("found at index %d\n", idx),
        Option.None => printf("not found\n"),
    }

    return 0;
}

import [printf] from "std/c.bpl";

# Result represents success or failure with error info
enum Result<T, E> {
    Ok(T),   # Success with value
    Err(E),  # Error with error info
}

struct DivError {
    message: string,
}

frame divide(a: int, b: int) ret Result<int, DivError> {
    if (b == 0) {
        return Result.Err(DivError { message: "Division by zero" });
    }
    return Result.Ok(a / b);
}

frame parseDigit(c: char) ret Result<int, string> {
    if (c >= '0' && c <= '9') {
        return Result.Ok(cast<int>(c) - cast<int>('0'));
    }
    return Result.Err("Not a digit");
}

frame main() ret int {
    # Division with Result
    printf("20 / 4 = ");
    match (divide(20, 4)) {
        Result.Ok(val) => printf("%d\n", val),
        Result.Err(e) => printf("Error: %s\n", e.message),
    }

    printf("20 / 0 = ");
    match (divide(20, 0)) {
        Result.Ok(val) => printf("%d\n", val),
        Result.Err(e) => printf("Error: %s\n", e.message),
    }

    # Parse digit
    printf("\nParse '7': ");
    match (parseDigit('7')) {
        Result.Ok(n) => printf("%d\n", n),
        Result.Err(msg) => printf("%s\n", msg),
    }

    printf("Parse 'x': ");
    match (parseDigit('x')) {
        Result.Ok(n) => printf("%d\n", n),
        Result.Err(msg) => printf("%s\n", msg),
    }

    return 0;
}

import [printf] from "std/c.bpl";

enum Message {
    Quit,
    Move(int, int),
    Write(string),
    ChangeColor(int, int, int),
}

frame processMessage(msg: Message) {
    match (msg) {
        # Match specific variant
        Message.Quit => {
            printf("Quit message received\n");
        },
        # Match and extract data
        Message.Move(x, y) => {
            printf("Move to (%d, %d)\n", x, y);
        },
        # Match with string
        Message.Write(text) => {
            printf("Write: %s\n", text);
        },
        # Match with multiple values
        Message.ChangeColor(r, g, b) => {
            printf("Change color to RGB(%d, %d, %d)\n", r, g, b);
        },
    }
}

frame main() ret int {
    processMessage(Message.Quit);
    processMessage(Message.Move(100, 200));
    processMessage(Message.Write("Hello!"));
    processMessage(Message.ChangeColor(255, 128, 0));

    return 0;
}

