import [printf] from "std/c.bpl";

enum Expr {
    Num(int),
    Add(int, int),
    Mul(int, int),
}

frame evaluate(expr: Expr) ret int {
    local result: int = 0;
    match (expr) {
        Expr.Num(n) => {
            result = n;
        },
        Expr.Add(a, b) => {
            result = a + b;
        },
        Expr.Mul(a, b) => {
            result = a * b;
        },
    }
    return result;
}

frame main() ret int {
    printf("Num(42) = %d\n", evaluate(Expr.Num(42)));
    printf("Add(10, 5) = %d\n", evaluate(Expr.Add(10, 5)));
    printf("Mul(6, 7) = %d\n", evaluate(Expr.Mul(6, 7)));

    return 0;
}
